import React, { useState, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import { StatusBadge } from '../../components/common/RequestCard';
import { requestAPI } from '../../utils/api';
import './AdminDashboard.css';

const NAV_ITEMS = [
  { path: '/admin', label: 'Dashboard', icon: '🏠', end: true },
];

const STATUS_OPTIONS = ['Pending', 'In Progress', 'Resolved'];
const STATUS_FILTERS = ['All', 'Pending', 'In Progress', 'Resolved'];
const CATEGORY_FILTERS = ['All', 'IT', 'Hostel', 'Academic', 'Administration'];

export default function AdminDashboard() {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [statusFilter, setStatusFilter] = useState('All');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [search, setSearch] = useState('');
  const [updatingId, setUpdatingId] = useState(null);

  useEffect(() => {
    const fetchRequests = async () => {
      try {
        const data = await requestAPI.getAllRequests();
        setRequests(data);
        setError(null);
      } catch (err) {
        setError(err.message || 'Failed to load requests');
      }
      setLoading(false);
    };

    fetchRequests();
  }, []);

  const stats = {
    total: requests.length,
    pending: requests.filter(r => r.status === 'Pending').length,
    inProgress: requests.filter(r => r.status === 'In Progress').length,
    resolved: requests.filter(r => r.status === 'Resolved').length,
  };

  const filtered = requests.filter(r => {
    const matchStatus = statusFilter === 'All' || r.status === statusFilter;
    const matchCategory = categoryFilter === 'All' || r.category === categoryFilter;
    const matchSearch = !search ||
      r.title.toLowerCase().includes(search.toLowerCase()) ||
      r.studentName.toLowerCase().includes(search.toLowerCase()) ||
      r.id.toLowerCase().includes(search.toLowerCase());
    return matchStatus && matchCategory && matchSearch;
  });

  const handleStatusChange = async (id, newStatus) => {
    setUpdatingId(id);
    try {
      await requestAPI.updateRequest(id, newStatus);
      const updated = requests.map(r =>
        r.id === id ? { ...r, status: newStatus } : r
      );
      setRequests(updated);
      setError(null);
    } catch (err) {
      setError(err.message || 'Failed to update request');
    }
    setUpdatingId(null);
  };

  return (
    <DashboardLayout navItems={NAV_ITEMS}>
      <div className="page-header">
        <h1 className="page-title">Admin Dashboard</h1>
        <p className="page-subtitle">Manage and respond to all student service requests</p>
      </div>

      {error && (
        <div className="alert alert-error animate-fade-up" style={{ marginBottom: 16 }}>
          ❌ {error}
        </div>
      )}

      {/* Stats */}
      <div className="admin-stats-grid animate-fade-up">
        <div className="admin-stat-card total">
          <div className="admin-stat-icon">📊</div>
          <div>
            <div className="admin-stat-num">{stats.total}</div>
            <div className="admin-stat-label">All Requests</div>
          </div>
        </div>
        <div className="admin-stat-card pending">
          <div className="admin-stat-icon">⏳</div>
          <div>
            <div className="admin-stat-num">{stats.pending}</div>
            <div className="admin-stat-label">Pending</div>
          </div>
        </div>
        <div className="admin-stat-card progress">
          <div className="admin-stat-icon">⚙️</div>
          <div>
            <div className="admin-stat-num">{stats.inProgress}</div>
            <div className="admin-stat-label">In Progress</div>
          </div>
        </div>
        <div className="admin-stat-card resolved">
          <div className="admin-stat-icon">✅</div>
          <div>
            <div className="admin-stat-num">{stats.resolved}</div>
            <div className="admin-stat-label">Resolved</div>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="card admin-filters animate-fade-up" style={{ animationDelay: '0.1s' }}>
        <input
          className="search-input"
          type="text"
          placeholder="Search by student name, title, or request ID..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
        <div className="filter-row">
          <div className="filter-group">
            <span className="filter-label">Status:</span>
            <div className="filter-chips">
              {STATUS_FILTERS.map(s => (
                <button key={s} className={`filter-chip ${statusFilter === s ? 'active' : ''}`} onClick={() => setStatusFilter(s)}>
                  {s}
                </button>
              ))}
            </div>
          </div>
          <div className="filter-group">
            <span className="filter-label">Category:</span>
            <div className="filter-chips">
              {CATEGORY_FILTERS.map(c => (
                <button key={c} className={`filter-chip ${categoryFilter === c ? 'active' : ''}`} onClick={() => setCategoryFilter(c)}>
                  {c}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Requests Table */}
      <div className="card animate-fade-up" style={{ animationDelay: '0.18s', overflow: 'hidden' }}>
        <div className="table-header-row">
          <span className="table-count">{filtered.length} request{filtered.length !== 1 ? 's' : ''}</span>
        </div>

        {loading ? (
          <div className="empty-state">
            <div className="spinner" style={{ marginBottom: 16 }} />
            <h3>Loading requests...</h3>
          </div>
        ) : filtered.length === 0 ? (
          <div className="empty-state">
            <div className="icon">📭</div>
            <h3>No requests found</h3>
            <p>Try adjusting your search or filters.</p>
          </div>
        ) : (
          <div className="table-scroll">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Request ID</th>
                  <th>Student Name</th>
                  <th>Category</th>
                  <th>Title</th>
                  <th>Submitted</th>
                  <th>Status</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map(r => (
                  <tr key={r.id} className={updatingId === r.id ? 'updating' : ''}>
                    <td><span className="req-id-cell">{r.id}</span></td>
                    <td>
                      <div className="student-cell">
                        <div className="student-mini-avatar">{r.studentName?.[0]?.toUpperCase()}</div>
                        <span>{r.studentName}</span>
                      </div>
                    </td>
                    <td><span className="category-chip">{r.category}</span></td>
                    <td>
                      <div className="req-title">{r.title}</div>
                      <div className="req-desc-preview">{r.description.slice(0, 50)}...</div>
                    </td>
                    <td className="date-cell">{new Date(r.createdAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}</td>
                    <td><StatusBadge status={r.status} /></td>
                    <td>
                      <select
                        className="status-select"
                        value={r.status}
                        onChange={e => handleStatusChange(r.id, e.target.value)}
                        disabled={updatingId === r.id}
                      >
                        {STATUS_OPTIONS.map(s => (
                          <option key={s} value={s}>{s}</option>
                        ))}
                      </select>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}
